# ---------------------------------------------------------------- font atlas
# Faces: 0 serif regular, 1 sans bold, 2 sans regular. Glyphs rendered at
# 48 px by the build-time generator; the blob is zlib-compressed base64.
# Blob layout per face: face id (1B), glyph count (2B), ascent (1B), then
# per glyph: codepoint (2B), w (1B), h (1B), dx (1B signed), dy (1B signed),
# advance (1B), then w*h grayscale bytes (0 = transparent, 255 = solid).
CHARSET = list(range(32, 127)) + [0x2014, 0x2013, 0x00B7, 0x2018, 0x2019,
                                  0x201C, 0x201D, 0x2022, 0x00D7, 0x2026,
                                  0x00DC, 0x00E9, 0x00ED, 0x00E3]
BASE = 48.0
GLYPHS = {}
ASCENT = {}


def _load_atlas():
    raw = zlib.decompress(base64.b64decode(ATLAS_B64))
    pos = 0
    while pos < len(raw):
        fi, count, ascent = struct.unpack_from(">BHB", raw, pos)
        pos += 4
        ASCENT[fi] = ascent
        table = {}
        for _ in range(count):
            cp, w, h, dx, dy, adv = struct.unpack_from(">HBBbbB", raw, pos)
            pos += 7
            px = raw[pos:pos + w * h]
            pos += w * h
            table[cp] = (w, h, dx, dy, adv, px)
        GLYPHS[fi] = table


# ------------------------------------------------------------------- canvas
buf = bytearray(W * H * 3)
for _i in range(0, W * H * 3, 3):
    buf[_i] = PAPER[0]
    buf[_i + 1] = PAPER[1]
    buf[_i + 2] = PAPER[2]


def fill_rect(x0, y0, x1, y1, color):
    x0 = max(0, x0)
    y0 = max(0, y0)
    x1 = min(W, x1)
    y1 = min(H, y1)
    r, g, b = color
    for y in range(y0, y1):
        base = y * W * 3 + x0 * 3
        for x in range(x1 - x0):
            i = base + x * 3
            buf[i] = r
            buf[i + 1] = g
            buf[i + 2] = b


def hline(x0, x1, y, color, thick=1):
    fill_rect(x0, y, x1, y + thick, color)


def vline(x, y0, y1, color, thick=1):
    fill_rect(x, y0, x + thick, y1, color)


def rect_outline(x0, y0, x1, y1, color, thick=1):
    hline(x0, x1, y0, color, thick)
    hline(x0, x1, y1 - thick, color, thick)
    vline(x0, y0, y1, color, thick)
    vline(x1 - thick, y0, y1, color, thick)


# ---------------------------------------------------------------------- PNG
def png_bytes():
    raw = bytearray()
    for y in range(H):
        raw.append(0)
        raw += buf[y * W * 3:(y + 1) * W * 3]
    comp = zlib.compress(bytes(raw), 6)

    def chunk(tag, data):
        out = struct.pack(">I", len(data)) + tag + data
        out += struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
        return out

    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr)
            + chunk(b"IDAT", comp) + chunk(b"IEND", b""))


# ------------------------------------------------------------ text rendering
SERIF, BOLD, SANS = 0, 1, 2
_cache = {}


def _scale_glyph(face, size, ch):
    key = (face, size, ch)
    g = _cache.get(key)
    if g is not None:
        return g
    table = GLYPHS[face]
    cp = ord(ch)
    if cp not in table:
        cp = 63  # '?'
    w, h, dx, dy, adv, px = table[cp]
    f = size / BASE
    if w == 0 or h == 0:
        g = (0, 0, 0, 0, max(1, int(round(adv * f))), b"")
        _cache[key] = g
        return g
    nw = max(1, int(round(w * f)))
    nh = max(1, int(round(h * f)))
    out = bytearray(nw * nh)
    if f >= 1.0:
        # upscale: nearest neighbour sampling
        for yy in range(nh):
            sy = min(h - 1, int(yy / f))
            for xx in range(nw):
                sx = min(w - 1, int(xx / f))
                out[yy * nw + xx] = px[sy * w + sx]
    else:
        # downscale: exact box-average over the covered source rectangle
        for yy in range(nh):
            sy0, sy1 = yy / f, (yy + 1) / f
            ylo, yhi = int(sy0), int(sy1)
            for xx in range(nw):
                sx0, sx1 = xx / f, (xx + 1) / f
                xlo, xhi = int(sx0), int(sx1)
                total = 0.0
                area = 0.0
                for sy in range(ylo, min(h, yhi + 1)):
                    wy = min(sy1, sy + 1.0) - max(sy0, float(sy))
                    if wy <= 0:
                        continue
                    for sx in range(xlo, min(w, xhi + 1)):
                        wx = min(sx1, sx + 1.0) - max(sx0, float(sx))
                        if wx <= 0:
                            continue
                        total += px[sy * w + sx] * wx * wy
                        area += wx * wy
                out[yy * nw + xx] = int(total / area) if area else 0
    g = (nw, nh, int(round(dx * f)), int(round(dy * f)),
         max(1, int(round(adv * f))), bytes(out))
    _cache[key] = g
    return g


def _blit(g, pen_x, baseline_y, color):
    nw, nh, dx, dy, adv, px = g
    if nw == 0 or nh == 0:
        return
    gx = int(pen_x) + dx
    gy = int(baseline_y) + dy
    r, gg, b = color
    for row in range(nh):
        yy = gy + row
        if yy < 0 or yy >= H:
            continue
        off = row * nw
        for col in range(nw):
            a = px[off + col]
            if a == 0:
                continue
            xx = gx + col
            if xx < 0 or xx >= W:
                continue
            i = (yy * W + xx) * 3
            if a == 255:
                buf[i] = r
                buf[i + 1] = gg
                buf[i + 2] = b
            else:
                buf[i] = (r * a + buf[i] * (255 - a)) // 255
                buf[i + 1] = (gg * a + buf[i + 1] * (255 - a)) // 255
                buf[i + 2] = (b * a + buf[i + 2] * (255 - a)) // 255


def text_width(text, face, size):
    total = 0
    for ch in text:
        total += _scale_glyph(face, size, ch)[4]
    return total


def wrap_text(text, face, size, width):
    words = text.split(" ")
    lines = []
    cur = ""
    for word in words:
        trial = word if not cur else cur + " " + word
        if text_width(trial, face, size) <= width or not cur:
            cur = trial
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines


def draw_line(x, baseline_y, text, face, size, color, align="left",
              width=None):
    pen = x
    if align in ("center", "right") and width is not None:
        tw = text_width(text, face, size)
        if align == "center":
            pen = x + (width - tw) // 2
        else:
            pen = x + width - tw
    for ch in text:
        g = _scale_glyph(face, size, ch)
        _blit(g, pen, baseline_y, color)
        pen += g[4]
    return pen


def draw_para(x, y_top, text, face, size, color, width, lh, max_lines=None):
    """Draw wrapped text; y_top is the top of the first line box.
    Returns the y just below the last drawn line."""
    lines = wrap_text(text, face, size, width)
    if max_lines is not None:
        lines = lines[:max_lines]
    ascent = int(round(ASCENT[face] * size / BASE))
    for i, line in enumerate(lines):
        draw_line(x, y_top + i * lh + ascent, line, face, size, color)
    return y_top + len(lines) * lh


