# ------------------------------------------------------------------- layout
def draw_map():
    mx0, my0, mx1, my1 = 24, 348, 660, 438
    fill_rect(mx0, my0, mx1, my1, MAPBG)
    cw = (mx1 - mx0) / 112.0
    ch = (my1 - my0) / 41.0
    for (r, c, n) in MAP_RUNS:
        for k in range(n):
            x = int(mx0 + (c + k) * cw)
            y = int(my0 + r * ch)
            fill_rect(x, y, x + 4, y + 2, MAPDOT)
    for (lon, lat) in MARKERS:
        px = int(mx0 + (lon + 180.0) / 360.0 * (mx1 - mx0))
        py = int(my0 + (90.0 - lat) / 150.0 * (my1 - my0))
        fill_rect(px - 5, py - 5, px + 5, py + 5, WHITE)
        fill_rect(px - 4, py - 4, px + 4, py + 4, RED)


